using System;
using XanaduYonder.Core;
using XanaduYonder.Core.Minesweeper;
using XanaduYonder.Runtime.Minesweeper;
internal static class Program
{
    private static int passed;
    private static void Main()
    {
        Check("ready flags do not start time, first reveal does",()=>{long t=100;var s=Session(()=>t);s.Execute(s.SessionId,0,true);t=5000;Eq(s.ElapsedMilliseconds,0);s.Execute(s.SessionId,40);t=5123;Eq(s.ElapsedMilliseconds,123);});
        Check("pause resume excludes repeated callbacks and background spans",()=>{long t=0;var s=Session(()=>t);s.Execute(s.SessionId,40);t=1234;s.Pause();t=9999;s.Pause();Eq(s.ElapsedMilliseconds,1234);s.Resume();t=10009;s.SetForeground(false);s.SetForeground(false);t=99999;s.SetForeground(true);s.SetForeground(true);Assert(s.Paused);Eq(s.ElapsedMilliseconds,1244);s.Resume();t=100009;Eq(s.ElapsedMilliseconds,1254);});
        Check("overview disables cells but continues active timing",()=>{long t=0;var s=Session(()=>t);s.Execute(s.SessionId,40);s.SetOverview(true);t=3000;Assert(!s.CanInteract&&s.CanView);Assert(!s.Execute(s.SessionId,0,true).Changed);Eq(s.ElapsedMilliseconds,3000);s.SetBlocked(true);Assert(!s.Overview&&s.Paused);t=5000;s.SetBlocked(false);Eq(s.ElapsedMilliseconds,3000);Assert(s.Paused);});
        Check("ready modal and background restore original manual pause",()=>{var s=Session(()=>0);s.SetBlocked(true);Assert(!s.CanView);s.SetBlocked(false);Assert(!s.Paused&&s.CanInteract);s.Pause();s.SetForeground(false);s.SetForeground(true);Assert(s.Paused);s.Resume();Assert(s.CanInteract);});
        Check("session identity and paused visibility block commands",()=>{var s=Session(()=>0);Assert(!s.Execute(Guid.NewGuid().ToString("D"),40).Changed);s.Leave();Assert(!s.Execute(s.SessionId,40).Changed);s.Enter();Assert(s.CanInteract);s.SetBlocked(true);Assert(!s.Execute(s.SessionId,40).Changed);s.SetBlocked(false);s.Execute(s.SessionId,40);s.Leave();s.Enter();Assert(s.Paused);});
        Check("view and mode persist precisely; active restore needs resume",()=>{long t=0;var s=Session(()=>t);s.SetInputMode(MinesweeperInputMode.Flag);s.SetView(true,.617123,2.34,6.78);s.SetInputMode(MinesweeperInputMode.Reveal);s.Execute(s.SessionId,40);t=1777;s.SetOverview(true);var data=s.Export();var restored=new MinesweeperSession(data,new RandomSource(),()=>100000);Assert(restored.Paused&&!restored.Overview&&restored.Fullscreen);Eq(restored.ElapsedMilliseconds,1777);Assert(restored.ZoomScale==.617123&&restored.CenterColumn==2.34&&restored.CenterRow==6.78);});
        Check("backwards source and elapsed overflow cannot wrap time",()=>{long t=0;var s=Session(()=>t);s.Execute(s.SessionId,40);t=10;s.Export();t=5;s.Export();t=11;Eq(s.ElapsedMilliseconds,11);var d=s.Export();d.ElapsedMilliseconds=long.MaxValue-1;var r=new MinesweeperSession(d,new RandomSource(),()=>t);r.Resume();t=100;Eq(r.ElapsedMilliseconds,long.MaxValue);});
        Check("win capture is one transaction with zero legal best and no recount",()=>{long t=0;var s=Session(()=>t);var p=new MinesweeperProfile();s.Execute(s.SessionId,40);var snap=s.Game.GetSnapshot();for(int i=0;i<81;i++)if(!snap.IsMine(i))s.Execute(s.SessionId,i);Assert(s.Game.State==MinesweeperState.Won);var data=p.Capture(s);Eq(data.Records[0].Wins,1);Eq(data.Records[0].BestMilliseconds.Value,0);Assert(data.Slots[0].ResultRecorded&&s.IsNewBest);t=1000;s.Resume();s.SetOverview(true);p.Capture(s);p.Capture(s);Eq(p.GetRecord(0).Wins,1);Eq(s.ElapsedMilliseconds,0);Assert(!s.Paused);Assert(data.TryValidate(out var reason),reason);var loaded=new MinesweeperProfile(data);var terminal=new MinesweeperSession(loaded.GetSlot(0),new RandomSource(),()=>t);loaded.Capture(terminal);Eq(loaded.GetRecord(0).Wins,1);});
        Check("loss capture freezes exact time and abandoning does not count",()=>{long t=0;var s=Session(()=>t);var p=new MinesweeperProfile();p.Capture(s);Eq(p.GetRecord(0).Losses,0);s.Execute(s.SessionId,40);t=987;var snap=s.Game.GetSnapshot();for(int i=0;i<81;i++)if(snap.IsMine(i)){s.Execute(s.SessionId,i);break;}p.Capture(s);t=9999;p.Capture(s);Eq(p.GetRecord(0).Losses,1);Eq(s.ElapsedMilliseconds,987);Assert(!p.GetRecord(0).BestMilliseconds.HasValue);var replacement=Session(()=>t);p.Capture(replacement);Eq(p.GetRecord(0).Losses,1);Assert(p.GetSlot(0).SessionId==replacement.SessionId);});
        Check("profile isolates slots and copies arrays and records",()=>{var p=new MinesweeperProfile();var s=Session(()=>0);p.Capture(s);var saved=p.Export();saved.Slots[0].ElapsedMilliseconds=99;saved.Records[0].Wins=5;saved.Slots[1]=saved.Slots[0];Eq(p.GetSlot(0).ElapsedMilliseconds,0);Eq(p.GetRecord(0).Wins,0);Assert(p.GetSlot(1)==null);});
        Check("duplicate resume does not discard a running time segment",()=>{long t=0;var s=Session(()=>t);s.Execute(s.SessionId,40);t=500;s.Resume();t=700;Eq(s.ElapsedMilliseconds,700);s.Resume();Eq(s.ElapsedMilliseconds,700);});
        Check("equal winning milliseconds do not announce a new record and counters saturate",()=>{var data=new MinesweeperSaveData();data.Records[0].Wins=long.MaxValue;data.Records[0].BestMilliseconds=0;var p=new MinesweeperProfile(data);var s=Session(()=>0);s.Execute(s.SessionId,40);var snap=s.Game.GetSnapshot();for(int i=0;i<81;i++)if(!snap.IsMine(i))s.Execute(s.SessionId,i);p.Capture(s);Eq(p.GetRecord(0).Wins,long.MaxValue);Assert(!s.IsNewBest);});
        Check("first action win freezes zero milliseconds and records once",()=>{long time=1000;var session=new MinesweeperSession(0,new ZeroRandom(),()=>time);time=5000;var result=session.Execute(session.SessionId,40);Assert(result.State==MinesweeperState.Won);Eq(session.ElapsedMilliseconds,0);var p=new MinesweeperProfile();p.Capture(session);time=9999;p.Capture(session);Eq(p.GetRecord(0).Wins,1);Eq(p.GetRecord(0).BestMilliseconds.Value,0);});
        Console.WriteLine("Minesweeper session: "+passed+" passed");
    }
    private static MinesweeperSession Session(Func<long> time){return new MinesweeperSession(0,new RandomSource(),time);}
    private static void Eq(long actual,long expected){Assert(actual==expected,actual+" != "+expected);}
    private static void Assert(bool value,string reason="Assertion failed"){if(!value)throw new Exception(reason);}
    private static void Check(string name,Action test){test();passed++;Console.WriteLine("PASS "+name);}
    private sealed class ZeroRandom:IRandomSource{public int Next(int n){return 0;}}
    private sealed class RandomSource:IRandomSource{private readonly Random random=new Random(8);public int Next(int n){return random.Next(n);}}
}
